    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 50-year-old patient presents with a slowly worsening ache in the proximal humerus. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Systemic chemotherapy", "Denosumab therapy", "Wide surgical resection", "Radiofrequency ablation", "High-dose radiation therapy"]'::jsonb, 2, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'An 9-year-old child sustains a minor ankle sprain. Radiographs are negative for fracture but show an incidental, 2 cm, eccentric, bubbly, cortically based radiolucent lesion with a thin sclerotic margin in the distal tibial metaphysis. The patient has no pain directly over the lesion. What is the most appropriate management?', '["Prophylactic internal fixation", "Curettage and bone grafting", "Immediate core needle biopsy", "Reassurance and observation", "MRI of the entire tibia"]'::jsonb, 3, 'This classic description is a Non-Ossifying Fibroma (NOF) or Fibrous Cortical Defect. These are asymptomatic, developmental defects seen in up to 30-40% of normal children. They invariably resolve/ossify spontaneously over time and require only observation unless they are large enough (>50% of bone diameter) to pose a risk of pathologic fracture.'),
    (v_topic_id, 'A 24-year-old male presents with deep, aching pain in the posterior spine that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Curettage and bone grafting", "Radiofrequency ablation (RFA)", "Radiation therapy", "Wide surgical resection", "Chemotherapy followed by limb-salvage surgery"]'::jsonb, 1, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 52-year-old patient complains of severe pain in the humerus. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Deposition of amyloid protein in the bone matrix", "Direct mechanical pressure from the tumor mass", "Osteoblast overactivation", "Ischemic necrosis of the medullary cavity"]'::jsonb, 0, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 30-year-old patient presents with a swollen, deformed hand. Radiographs show multiple centrally located radiolucent lesions with stippled calcifications within the phalanges and metacarpals. Physical exam reveals multiple soft tissue hemangiomas on the same limb. What is the diagnosis?', '["McCune-Albright syndrome", "Maffucci syndrome", "Neurofibromatosis type 1", "Multiple hereditary exostoses", "Ollier disease"]'::jsonb, 1, 'Enchondromas are benign cartilage tumors of the medullary cavity, frequently found in the small bones of the hands and feet. Multiple enchondromas alone characterize Ollier disease. When multiple enchondromas are accompanied by soft tissue hemangiomas, it is called Maffucci syndrome, which carries a much higher risk of malignant transformation to chondrosarcoma and other visceral malignancies.'),
    (v_topic_id, 'A 6-year-old patient has intense nocturnal pain in the femur that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Open en bloc resection", "Radiation therapy", "Intra-articular steroid injection", "Cryoablation without imaging", "CT-guided radiofrequency ablation (RFA)"]'::jsonb, 4, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 47-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal humerus. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Achieving a biologic union of the fracture site without cement", "Preventing pulmonary metastasis", "Curative resection of the tumor with wide margins", "Immediate pain relief, early mobilization, and restoration of function", "Delaying surgery until radiation therapy is completed"]'::jsonb, 3, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 32-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis", "Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet", "Dissect extensively through intermuscular planes to avoid muscle damage", "Use a transverse incision parallel to skin tension lines for a better cosmetic result", "Use a longitudinal incision placed within the planned definitive resection ellipse"]'::jsonb, 4, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 16-year-old patient presents with chronic, dull knee pain. Radiographs reveal a well-demarcated, small lytic lesion exclusively located within the epiphysis of the proximal tibia. Biopsy shows ''chicken-wire'' calcifications and mononuclear cells. What is the most likely diagnosis?', '["Osteosarcoma", "Chondromyxoid fibroma", "Enchondroma", "Giant Cell Tumor", "Chondroblastoma"]'::jsonb, 4, 'Chondroblastoma is a rare, benign cartilage-forming tumor that characteristically occurs in the epiphysis (or apophysis) of long bones in skeletally immature patients (unlike Giant Cell Tumors, which usually occur after physeal closure). Histology classically shows ''''chicken-wire'''' calcifications.'),
    (v_topic_id, 'A 49-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal tibia. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Immediate pain relief, early mobilization, and restoration of function", "Curative resection of the tumor with wide margins", "Achieving a biologic union of the fracture site without cement", "Preventing pulmonary metastasis", "Delaying surgery until radiation therapy is completed"]'::jsonb, 0, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 68-year-old patient complains of severe pain in the radius. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Ischemic necrosis of the medullary cavity", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Osteoblast overactivation", "Direct mechanical pressure from the tumor mass", "Deposition of amyloid protein in the bone matrix"]'::jsonb, 1, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 18-year-old male presents with deep, aching pain in the proximal femur that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Intravenous bisphosphonates", "Radiation therapy", "Curettage and bone grafting", "Wide surgical resection", "Radiofrequency ablation (RFA)"]'::jsonb, 4, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
